function jaTerm(value: string) { if (JA[value]) return JA[value]; return JA_REPLACE.reduce((text,[from,to]) => text.replaceAll(from,to), value); }
function localizedExam(value: string, language: Language) {
  if (language === "zh") return value;
  return value
    .replaceAll("专业", "専門")
    .replaceAll("选择题对照", "選択肢比較")
    .replaceAll("剧场类型对照", "劇場類型比較")
    .replaceAll("办公建筑对照", "オフィス建築比較");
}

function Label({ value, language, question = false }: { value: string; language: Language; question?: boolean; inverse?: boolean }) {
  const japanese = question ? (JA_QUESTIONS[value] ?? jaTerm(value)) : jaTerm(value);
  if (language === "zh") return <>{value}</>;
  return <span lang="ja">{japanese}</span>;
}

