const AXIS_FALLBACKS: Record<string, Omit<SemanticPatternRule, "match">> = {
  "住户内部":{cue:"房间、服务空间与家庭活动之间形成明确的邻接和边界关系。",cueJa:"室・サービス空間・家族活動の間に明確な近接と境界が現れる。",definition:"通过房间连接和边界组织家庭生活的一种住户平面形式。",definitionJa:"室の接続と境界によって家族生活を組織する住戸平面形式。",gain:"使生活行为、私密和空间使用相互协调",gainJa:"生活行為・プライバシー・空間利用を調整できる",cost:"家庭变化后的适应性和有限面积中的冲突",costJa:"家族変化への適応性と限られた面積での衝突"},
  "展示环境":{cue:"展室的开口、顶棚、照明和外部视线呈现明确控制。",cueJa:"展示室の開口・天井・照明・外部視線が明確に制御される。",definition:"根据作品观看和保存条件形成的一种展示环境。",definitionJa:"作品の鑑賞・保存条件に応じてつくられる展示環境。",gain:"改善作品观看条件和空间体验",gainJa:"作品の鑑賞条件と空間体験を改善する",cost:"能耗、维护和不同展览要求之间的矛盾",costJa:"エネルギー、維持管理、異なる展示要求の矛盾"},
};

function inferredPatternInfo(pattern: string, axis: Axis): PatternInfo {
  const rule = SEMANTIC_PATTERN_RULES.find((item) => item.match.test(pattern)) ?? AXIS_FALLBACKS[axis.name];
  const confused = axis.patterns.filter((item) => item !== pattern).slice(0, 3);
  if (rule) return {
    cue: rule.cue, cueJa: rule.cueJa,
    definition: rule.definition, definitionJa: rule.definitionJa,
    exam: `${rule.gain}；但需要同时检讨${rule.cost}。`,
    examJa: `${rule.gainJa}一方、${rule.costJa}を同時に検討する必要がある。`,
    confused,
  };
  return {
    cue: `图面中“${pattern}”表现为区别于同轴其他类型的空间、边界或动线关系。`,
    cueJa: `図面では「${jaTerm(pattern)}」に固有の空間・境界・動線関係を同じ分析軸の他類型と比較する。`,
    definition: `“${pattern}”是回答“${axis.question}”的一种具体计划形式。`,
    definitionJa: `「${jaTerm(pattern)}」は「${JA_QUESTIONS[axis.question] ?? jaTerm(axis.question)}」に対する具体的な計画形式である。`,
    exam: "说明图面上的构成关系、它解决的计划问题，并评价由此产生的收益与限制。",
    examJa: "図面上の構成、それが解決する計画課題、そこから生じる効果と制約を述べる。",
    confused,
  };
}

